+    }
+
+    * {
+      box-sizing: border-box;
+    }
+
+    body {
+      margin: 0;
+      min-height: 100vh;
+      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+      background:
+        radial-gradient(circle at top, rgba(91, 140, 255, 0.18), transparent 35%),
+        linear-gradient(180deg, #0b1020 0%, #070b15 100%);
+      color: var(--text);
+      display: grid;
+      place-items: center;
+      padding: 32px 16px;
+    }
+
+    .page {
+      width: min(920px, 100%);
+      background: linear-gradient(180deg, rgba(17, 24, 45, 0.96), rgba(11, 16, 32, 0.96));
+      border: 1px solid var(--border);
+      border-radius: 24px;
+      box-shadow: var(--shadow);
+      overflow: hidden;
+    }
+
+    header {
+      padding: 32px 32px 20px;
+      border-bottom: 1px solid rgba(255, 255, 255, 0.06);
+      background: linear-gradient(180deg, rgba(22, 33, 58, 0.8), transparent);
+    }
+
+    h1 {
+      margin: 0 0 10px;
+      font-size: clamp(2rem, 4vw, 3rem);
+      letter-spacing: -0.04em;
+    }
+
+    p {
+      margin: 0;
+      color: var(--muted);
+      line-height: 1.6;
+    }
+
+    .faq {
+      padding: 24px;
+      display: grid;
+      gap: 14px;
+    }
+
+    .example {
+      border: 1px solid rgba(255, 255, 255, 0.08);
+      border-radius: 18px;
+      background: linear-gradient(180deg, rgba(22, 33, 58, 0.95), rgba(17, 24, 45, 0.95));
+      overflow: hidden;
+      transition: border-color 180ms ease, transform 180ms ease, box-shadow 180ms ease;
+    }
+
+    .example:hover {
+      border-color: rgba(141, 180, 255, 0.3);
+      transform: translateY(-1px);
+      box-shadow: 0 14px 30px rgba(0, 0, 0, 0.18);
+    }
+
+    .question {
+      width: 100%;
+      border: 0;
+      background: transparent;
+      color: inherit;
+      text-align: left;
+      padding: 22px 24px;
+      font: inherit;
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 16px;
+      cursor: pointer;
+    }
+
+    .question strong {
+      font-size: 1.05rem;
+      letter-spacing: -0.01em;
+    }
+
+    .icon {
+      flex: none;
+      width: 34px;
+      height: 34px;
+      border-radius: 999px;
+      display: grid;
+      place-items: center;
+      background: rgba(141, 180, 255, 0.12);
+      color: var(--accent);
+      transition: transform 180ms ease, background 180ms ease;
+    }
+
+    .details {
+      display: none;
+      padding: 0 24px 22px;
+      color: var(--muted);
+      line-height: 1.75;
+    }
+
+    .example.open .details {
+      display: block;
+    }
+
+    .example.open .icon {
+      transform: rotate(45deg);
+      background: rgba(91, 140, 255, 0.18);
+    }
+
+    .details p {
+      margin: 0;
+    }
+
+    @media (max-width: 640px) {
+      header,
+      .faq {
+        padding-left: 18px;
+        padding-right: 18px;
+      }
+
+      .question,
+      .details {
+        padding-left: 18px;
+        padding-right: 18px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main class="page">
+    <header>
+      <h1>Cat FAQ</h1>
+      <p>Answers to the most common questions about our favorite mysterious roommates.</p>
+    </header>
+
+    <section class="faq" aria-label="Frequently asked questions about cats">
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false">
+          <strong>Why do cats sleep so much?</strong>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details">
+          <p>Cats conserve energy for short bursts of activity, so a long nap schedule is completely normal. A cozy cat is usually a healthy cat.</p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false">
+          <strong>Why does my cat bring me toys?</strong>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details">
+          <p>Your cat may be sharing a prize, practicing hunting behavior, or simply showing affection. It is a compliment, even if it arrives at 3 a.m.</p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false">
+          <strong>Do cats like routines?</strong>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details">
+          <p>Yes. Cats usually feel safest when meals, play, and quiet time happen predictably. Small routines help them stay relaxed and confident.</p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false">
+          <strong>How can I tell if my cat is happy?</strong>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details">
+          <p>Look for slow blinks, relaxed posture, steady appetite, grooming, and calm curiosity. A cat choosing to sit near you is also a strong hint.</p>
+        </div>
+      </div>
+    </section>
+  </main>
+
+  <script>
+    document.querySelectorAll(".example").forEach((example) => {
+      const button = example.querySelector(".question");
+      const details = example.querySelector(".details");
+
+      button.addEventListener("click", () => {
+        const isOpen = example.classList.toggle("open");
+        button.setAttribute("aria-expanded", String(isOpen));
+        details.hidden = !isOpen;
+      });
+
+      details.hidden = true;
+    });
+  </script>
+</body>
+</html>
*** End Patch
